// Modbus RTU primitives and the THT-02 behaviour model. Mirrors core/modbus.py;
// parity is checked at runtime against the golden vectors generated by Python.

export const DIP_WEIGHTS = [128, 64, 32, 16, 8, 4, 2, 1];
export const SENSOR_ABNORMAL = 0x7fff;
export const RESPONSE_TIMEOUT_MS = 1000;
export const INJECTIONS = ['none', 'bad_crc', 'foreign_address', 'sensor_fault'];
const READ = 0x03;
const REGISTERS = 8;

export function crc16(bytes) {
  let crc = 0xffff;
  for (const b of bytes) {
    crc ^= b;
    for (let i = 0; i < 8; i++) crc = crc & 1 ? (crc >>> 1) ^ 0xa001 : crc >>> 1;
  }
  return crc;
}

export const withCrc = pdu => {
  const c = crc16(pdu);
  return [...pdu, c & 0xff, c >>> 8];
};
export const crcOk = f => f.length >= 4 && crc16(f.slice(0, -2)) === (f[f.length - 2] | (f[f.length - 1] << 8));
export const hex = f => (f ? f.map(b => b.toString(16).toUpperCase().padStart(2, '0')).join(' ') : null);
export const fromHex = s => (s ? s.split(' ').map(h => parseInt(h, 16)) : null);

export function dipToAddress(bits) {
  if (bits.length !== 8 || bits.some(b => b !== 0 && b !== 1)) throw new Error('DIP state must be 8 values of 0 or 1.');
  return bits.reduce((sum, b, i) => sum + (b ? DIP_WEIGHTS[i] : 0), 0);
}
export const addressToDip = a => DIP_WEIGHTS.map(w => (a & w ? 1 : 0));

export function readRequest(address, start = 0, quantity = 2) {
  if (address < 1 || address > 247) throw new Error('Master polling address must be 1..247.');
  return withCrc([address, READ, start >> 8, start & 0xff, quantity >> 8, quantity & 0xff]);
}

export class Tht02Model {
  constructor(dipBits, temperatureC = 23.4, humidityRh = 57.8) {
    this.dipBits = [...dipBits];
    this.temperatureC = temperatureC;
    this.humidityRh = humidityRh;
    this.baud = 9600;
    this.elementFault = false;
  }

  get address() { return dipToAddress(this.dipBits); }

  registers() {
    const t = this.elementFault ? SENSOR_ABNORMAL : Math.round(this.temperatureC * 10) & 0xffff;
    const h = this.elementFault ? SENSOR_ABNORMAL : Math.round(this.humidityRh * 10);
    return [t, h, 0, 0, this.address, this.baud, 0x0600, 0x000a];
  }

  transact(req) {
    if (req.length < 4 || !crcOk(req)) return null;
    const [address, fn] = req;
    if (address === 0 || address !== this.address) return null;
    if (fn !== READ) return withCrc([address, fn | 0x80, 0x01]);
    if (req.length !== 8) return withCrc([address, 0x83, 0x03]);
    const start = (req[2] << 8) | req[3];
    const qty = (req[4] << 8) | req[5];
    if (qty < 1 || start + qty > REGISTERS) return withCrc([address, 0x83, 0x02]);
    const data = this.registers().slice(start, start + qty).flatMap(v => [(v >> 8) & 0xff, v & 0xff]);
    return withCrc([address, READ, data.length, ...data]);
  }
}

export function decodeRead(resp, expected, start = 0, quantity = 2) {
  const checks = [];
  const check = (name, ok, detail) => { checks.push({ check: name, ok: !!ok, detail }); return ok; };
  const result = { status: 'invalid', valid: false, checks, values: null, exception: null };
  const h2 = n => '0x' + n.toString(16).toUpperCase().padStart(2, '0');
  if (resp === null) {
    check('response', false, `No reply within ${RESPONSE_TIMEOUT_MS} ms`);
    result.status = 'timeout';
    return result;
  }
  if (!check('length', resp.length >= 5, `${resp.length} bytes`)) return result;
  const crc = crcOk(resp);
  if (!check('crc', crc, 'CRC-16/MODBUS ' + (crc ? 'matches' : 'mismatch'))) return result;
  if (!check('address', resp[0] === expected, `${h2(resp[0])} (expected ${h2(expected)})`)) return result;
  if (resp[1] === (READ | 0x80)) {
    check('function', false, `Exception ${h2(resp[2])}`);
    return Object.assign(result, { status: 'exception', exception: resp[2] });
  }
  if (!check('function', resp[1] === READ, h2(resp[1]))) return result;
  const n = 2 * quantity;
  if (!check('byte_count', resp[2] === n && resp.length === 5 + n, `${resp[2]} data bytes (expected ${n})`)) return result;
  const regs = {};
  for (let i = 0; i < quantity; i++) regs[start + i] = (resp[3 + 2 * i] << 8) | resp[4 + 2 * i];
  const abnormal = [0, 1].filter(r => regs[r] === SENSOR_ABNORMAL);
  if (!check('sensor_marker', !abnormal.length, abnormal.length ? '7FFF H on register ' + abnormal.join(', ') : 'no 7FFF H marker')) {
    result.status = 'sensor_abnormal';
    return result;
  }
  const values = {};
  const r1 = x => Math.round(x) / 10;
  if (0 in regs) values.temperature_c = r1(regs[0] & 0x8000 ? regs[0] - 0x10000 : regs[0]);
  if (1 in regs) values.humidity_rh = r1(regs[1]);
  return Object.assign(result, { status: 'valid', valid: true, values });
}

export function poll(master, model, injection = 'none', start = 0, quantity = 2) {
  if (!INJECTIONS.includes(injection)) throw new Error('Unknown injection.');
  const req = readRequest(master, start, quantity);
  const fault = model.elementFault;
  if (injection === 'sensor_fault') model.elementFault = true;
  let resp;
  try { resp = model.transact(req); } finally { model.elementFault = fault; }
  if (resp && injection === 'bad_crc') resp = [...resp.slice(0, -1), resp[resp.length - 1] ^ 0x5a];
  if (resp && injection === 'foreign_address') resp = withCrc([(resp[0] % 247) + 1, ...resp.slice(1, -2)]);
  return {
    source: 'simulated',
    master_address: master,
    device_address: model.address,
    injection,
    request_hex: hex(req),
    response_hex: hex(resp),
    decode: decodeRead(resp, master, start, quantity),
  };
}

// Field roles for colouring frame bytes in the UI.
export function annotate(frameHex, kind) {
  const b = fromHex(frameHex);
  if (!b) return [];
  return b.map((v, i) => {
    let role = 'data';
    if (i === 0) role = 'addr';
    else if (i === 1) role = 'fn';
    else if (i >= b.length - 2) role = 'crc';
    else if (kind === 'response' && i === 2 && b[1] === READ) role = 'count';
    return { hex: v.toString(16).toUpperCase().padStart(2, '0'), role };
  });
}

// Compare this implementation with the Python golden vectors.
export function parityCheck(golden) {
  const failures = [];
  const manual = new Tht02Model(addressToDip(1), 25.0, 60.0);
  const req = readRequest(1, 0, 8);
  if (hex(req) !== golden.manual_request) failures.push('manual request');
  if (hex(manual.transact(req)) !== golden.manual_response) failures.push('manual response');
  const cases = {
    incident: () => poll(1, new Tht02Model(addressToDip(2))),
    fixed: () => poll(1, new Tht02Model(addressToDip(1))),
    bad_crc: () => poll(1, new Tht02Model(addressToDip(1)), 'bad_crc'),
    foreign_address: () => poll(1, new Tht02Model(addressToDip(1)), 'foreign_address'),
    sensor_fault: () => poll(1, new Tht02Model(addressToDip(1)), 'sensor_fault'),
  };
  for (const [name, run] of Object.entries(cases)) {
    const a = run();
    const g = golden[name];
    if (!g || a.request_hex !== g.request_hex || a.response_hex !== g.response_hex || a.decode.status !== g.decode.status
      || JSON.stringify(a.decode.values) !== JSON.stringify(g.decode.values)) failures.push(name);
  }
  return { ok: failures.length === 0, cases: 2 + Object.keys(cases).length, failures };
}
